const crypto = require('crypto');

const RELEVANT = /eligib|income|salary|salaried|self[- ]employed|business|professional|age\b|years|cibil|credit score|interest|rate|% p\.a|tenure|loan amount|lakh|crore|processing fee|experience|employ|nationality|resident|itr|turnover/i;
const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', rsquo: "'", lsquo: "'", ndash: '-', mdash: '-', rupee: '₹' };

const decode = (text) =>
  text
    .replace(/&#(\d+);/g, (_, digits) => String.fromCodePoint(Number(digits)))
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&([a-z]+);/gi, (entity, name) => ENTITIES[name.toLowerCase()] ?? entity);

const toLines = (html) =>
  html
    .replace(/<(script|style|noscript|svg|iframe|header|nav|footer)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<\/?(p|li|div|br|h[1-6]|tr|td|th|section|article|ul|ol|table)\b[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');

function readableLines(html) {
  return toLines(decode(toLines(html)))
    .split('\n')
    .map((line) => decode(line).replace(/\s+/g, ' ').trim())
    .filter((line) => line.length > 2);
}

function relevantText(html) {
  const lines = readableLines(html);
  const keep = new Set();
  lines.forEach((line, index) => {
    if (line.length < 600 && !line.includes('":') && RELEVANT.test(line)) keep.add(index - 1).add(index).add(index + 1);
  });
  const picked = [...keep].sort((a, b) => a - b).map((index) => lines[index]).filter(Boolean);
  return [...new Set(picked)].join('\n').slice(0, 16000);
}

const source = $('Loop over sources').item.json;
const text = relevantText(String($json.html));
const contentHash = crypto.createHash('sha256').update(text).digest('hex');

return {
  json: {
    ...source,
    text,
    content_hash: contentHash,
    changed: contentHash !== source.last_hash,
  },
};

const crypto = require('crypto');

const page = $('Build extraction request').item.json;
const EMPLOYMENT = ['salaried', 'self_employed', 'business'];

const inRange = (value, low, high) => (typeof value === 'number' && value >= low && value <= high ? value : null);
const text = (value) => (typeof value === 'string' && value.trim() ? value.trim() : null);

let extracted = [];
try {
  extracted = JSON.parse($json.choices[0].message.content).products ?? [];
} catch (error) {
  extracted = [];
}

const products = new Map();
for (const product of extracted) {
  const lender = text(product.lender);
  const productName = text(product.product_name);
  if (!lender || !productName) continue;

  const employment = (product.employment_types ?? []).filter((type) => EMPLOYMENT.includes(type));
  const criteria = {
    interest_rate_min: inRange(product.interest_rate_min, 5, 45),
    interest_rate_max: inRange(product.interest_rate_max, 5, 45),
    min_monthly_income: inRange(product.min_monthly_income, 5000, 500000),
    min_credit_score: inRange(product.min_credit_score, 300, 900),
    max_credit_score: inRange(product.max_credit_score, 300, 900),
    min_age: inRange(product.min_age, 18, 80),
    max_age: inRange(product.max_age, 18, 80),
    employment_types: employment.length === 0 || employment.length === EMPLOYMENT.length ? null : employment,
    qualitative_criteria: text(product.qualitative_criteria),
  };

  products.set(`${lender}|${productName}`.toLowerCase(), {
    lender,
    product_name: productName,
    ...criteria,
    max_amount: inRange(product.max_amount, 10000, 100000000),
    max_tenure_months: inRange(product.max_tenure_months, 1, 120),
    processing_fee: text(product.processing_fee),
    extraction_confidence: inRange(product.confidence, 0, 1),
    criteria_hash: crypto.createHash('sha256').update(JSON.stringify(criteria)).digest('hex'),
  });
}

return {
  json: {
    source_id: page.source_id,
    url: page.url,
    content_hash: page.content_hash,
    products: [...products.values()],
  },
};
